/** Public routes (same slug in both languages; French lives under /fr). */
export const PAGES = ["", "features", "pricing", "licensing", "industries", "about", "contact", "privacy", "terms"] as const;
export type Page = (typeof PAGES)[number];

export function href(lang: Lang, page: Page | string): string {
  const p = page ? `/${page}` : "";
  return lang === "fr" ? `/fr${p}` || "/fr" : p || "/";
}

